export interface WorldStateHandle {
  entities: Record<string, string>;
}

const FEN = "Fen";
const PEX = "pex";
const DOR = "dor";

const cloneState = (state: WorldStateHandle): WorldStateHandle => ({
  entities: { ...state.entities },
});

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return {
      entities: {
        [FEN]: PEX,
      },
    };
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string } {
    const currentState = state.entities[FEN];

    if (operationDisplayName === "advanceFen") {
      if (currentState !== PEX) {
        return {
          success: false,
          error: `advanceFen requires ${FEN} to be in ${PEX}`,
        };
      }

      const newState = cloneState(state);
      newState.entities[FEN] = DOR;
      return { success: true, newState };
    }

    if (operationDisplayName === "recoverFen") {
      if (currentState !== DOR) {
        return {
          success: false,
          error: `recoverFen requires ${FEN} to be in ${DOR}`,
        };
      }

      const newState = cloneState(state);
      newState.entities[FEN] = PEX;
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldStateHandle, entityDisplayName: string): string {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return { ...state.entities };
  },
};
